        assertDeliveryThrows("配送费 负金额", new BigDecimal("-0.01"), 1);
        assertDeliveryThrows("配送费 负金额大", new BigDecimal("-100"), 1);
        assertDeliveryThrows("配送费 负件数", new BigDecimal("100"), -1);
