        assertService("服务费 金额0", "0.00", new BigDecimal("0"));
        assertService("服务费 金额0.01", "2.00", new BigDecimal("0.01"));
        assertService("服务费 金额1", "2.00", new BigDecimal("1"));
        assertService("服务费 金额99.99", "2.00", new BigDecimal("99.99"));
