            failed++;
            System.out.println("[失败] " + name + " 期望抛 IllegalArgumentException 但未抛出");
        } catch (IllegalArgumentException e) {
            passed++;
        } catch (Exception e) {
            failed++;
            System.out.println("[失败] " + name + " 抛出非预期异常: " + e);
