```java
import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 配送费与服务费计算工具类。
 * 金额单位：元。所有金额返回值保留 2 位小数。
 */
public final class FeeCalculator {

    private static final BigDecimal DELIVERY_FREE_THRESHOLD = new BigDecimal("200");
    private static final BigDecimal SERVICE_LOW_THRESHOLD = new BigDecimal("100");
    private static final BigDecimal DELIVERY_FEE = new BigDecimal("12");
    private static final BigDecimal SERVICE_FEE_LOW = new BigDecimal("2");
    private static final BigDecimal SERVICE_FEE_HIGH = new BigDecimal("5");

    private FeeCalculator() {
    }

    /**
     * 计算配送费。
     * 规则：件数为 0 返回 0；件数大于 0 且金额严格大于 200 返回 0；否则返回 12。
     *
     * @param amount    订单金额，不能为 null 且必须大于等于 0
     * @param itemCount 件数，不能小于 0
     * @return 配送费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null、amount 小于 0 或 itemCount 小于 0
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        if (amount == null) {
            throw new IllegalArgumentException("订单金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("订单金额不能为负数: " + amount);
        }
        if (itemCount < 0) {
            throw new IllegalArgumentException("件数不能为负数: " + itemCount);
        }

        if (itemCount == 0) {
            return scale(BigDecimal.ZERO);
        }
        if (amount.compareTo(DELIVERY_FREE_THRESHOLD) > 0) {
            return scale(BigDecimal.ZERO);
        }
        return scale(DELIVERY_FEE);
    }

    /**
     * 计算服务费。
     * 规则：金额为 0 返回 0；大于 0 且不超过 100 返回 2；严格大于 100 返回 5。
     *
     * @param amount 订单金额，不能为 null 且必须大于等于 0
     * @return 服务费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null 或 amount 小于 0
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("订单金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("订单金额不能为负数: " + amount);
        }

        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return scale(BigDecimal.ZERO);
        }
        if (amount.compareTo(SERVICE_LOW_THRESHOLD) <= 0) {
            return scale(SERVICE_FEE_LOW);
        }
        return scale(SERVICE_FEE_HIGH);
    }

    private static BigDecimal scale(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_UP);
    }
}
```

## FeeCalculatorTest.java

```java
import java.math.BigDecimal;

/**
 * FeeCalculator 边界测试，使用 main 加断言，不依赖测试框架。
 */
public final class FeeCalculatorTest {

    private static final BigDecimal ZERO = new BigDecimal("0.00");
    private static final BigDecimal TWO = new BigDecimal("2.00");
    private static final BigDecimal FIVE = new BigDecimal("5.00");
    private static final BigDecimal TWELVE = new BigDecimal("12.00");

    private FeeCalculatorTest() {
    }

    public static void main(String[] args) {
        testDeliveryFee();
        testServiceFee();
        testInvalidInputs();
        testInputNotModified();
        System.out.println("全部测试通过");
    }

    private static void testDeliveryFee() {
        // 件数 0 返回 0
        assertEquals(ZERO, FeeCalculator.deliveryFee(new BigDecimal("0"), 0), "件数0金额0");
        assertEquals(ZERO, FeeCalculator.deliveryFee(new BigDecimal("200"), 0), "件数0金额200");
        assertEquals(ZERO, FeeCalculator.deliveryFee(new BigDecimal("999"), 0), "件数0金额999");

        // 件数 1，金额严格大于 200 返回 0
        assertEquals(ZERO, FeeCalculator.deliveryFee(new BigDecimal("200.01"), 1), "件数1金额200.01");
        assertEquals(ZERO, FeeCalculator.deliveryFee(new BigDecimal("201"), 1), "件数1金额201");

        // 金额恰好 200 返回 12
        assertEquals(TWELVE, FeeCalculator.deliveryFee(new BigDecimal("200"), 1), "件数1金额200");

        // 金额不大于 200 返回 12
        assertEquals(TWELVE, FeeCalculator.deliveryFee(new BigDecimal("199.99"), 1), "件数1金额199.99");
        assertEquals(TWELVE, FeeCalculator.deliveryFee(new BigDecimal("100"), 1), "件数1金额100");
        assertEquals(TWELVE, FeeCalculator.deliveryFee(new BigDecimal("0"), 1), "件数1金额0");

        // 多件数
        assertEquals(ZERO, FeeCalculator.deliveryFee(new BigDecimal("200.01"), 5), "件数5金额200.01");
        assertEquals(TWELVE, FeeCalculator.deliveryFee(new BigDecimal("200"), 5), "件数5金额200");
    }

    private static void testServiceFee() {
        // 金额为 0 返回 0
        assertEquals(ZERO, FeeCalculator.serviceFee(new BigDecimal("0")), "服务费金额0");

        // 大于 0 且不超过 100 返回 2
        assertEquals(TWO, FeeCalculator.serviceFee(new BigDecimal("0.01")), "服务费金额0.01");
        assertEquals(TWO, FeeCalculator.serviceFee(new BigDecimal("100")), "服务费金额100");

        // 严格大于 100 返回 5
        assertEquals(FIVE, FeeCalculator.serviceFee(new BigDecimal("100.01")), "服务费金额100.01");
        assertEquals(FIVE, FeeCalculator.serviceFee(new BigDecimal("200")), "服务费金额200");
        assertEquals(FIVE, FeeCalculator.serviceFee(new BigDecimal("201")), "服务费金额201");

        // 服务费不使用配送费 200 阈值：200 仍为 5
        assertEquals(FIVE, FeeCalculator.serviceFee(new BigDecimal("200")), "服务费200阈值不适用");
    }

    private static void testInvalidInputs() {
        // null 金额
        assertThrows(() -> FeeCalculator.deliveryFee(null, 1), "配送费 null 金额");
        assertThrows(() -> FeeCalculator.serviceFee(null), "服务费 null 金额");

        // 负金额
        assertThrows(() -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1), "配送费负金额");
        assertThrows(() -> FeeCalculator.serviceFee(new BigDecimal("-0.01")), "服务费负金额");

        // 负件数
        assertThrows(() -> FeeCalculator.deliveryFee(new BigDecimal("100"), -1), "配送费负件数");
    }

    private static void testInputNotModified() {
        BigDecimal amount = new BigDecimal("200.005");
        BigDecimal original = new BigDecimal(amount.toPlainString());
        FeeCalculator.deliveryFee(amount, 1);
        FeeCalculator.serviceFee(amount);
        if (amount.compareTo(original) != 0) {
            throw new AssertionError("输入 BigDecimal 被修改: " + amount);
        }
    }

    private static void assertEquals(BigDecimal expected, BigDecimal actual, String message) {
        if (expected.compareTo(actual) != 0) {
            throw new AssertionError(message + " 期望: " + expected + " 实际: " + actual);
        }
        if (actual.scale() != 2) {
            throw new AssertionError(message + " 返回值精度应为 2 位，实际: " + actual.scale());
        }
    }

    private static void assertThrows(Runnable action, String message) {
        try {
            action.run();
        } catch (IllegalArgumentException e) {
            return;
        }
        throw new AssertionError(message + " 应抛出 IllegalArgumentException");
    }
}
