```java
import java.math.BigDecimal;
import java.math.RoundingMode;

public final class FeeCalculator {

    private static final BigDecimal ZERO = new BigDecimal("0");
    private static final BigDecimal TWO_HUNDRED = new BigDecimal("200");
    private static final BigDecimal ONE_HUNDRED = new BigDecimal("100");
    private static final BigDecimal DELIVERY_FEE = new BigDecimal("12");
    private static final BigDecimal SERVICE_FEE_LOW = new BigDecimal("2");
    private static final BigDecimal SERVICE_FEE_HIGH = new BigDecimal("5");

    private FeeCalculator() {
    }

    /**
     * 配送费规则：
     * 1. itemCount == 0 返回 0；
     * 2. itemCount > 0 且 amount > 200 返回 0；
     * 3. 其他情况返回 12。
     *
     * @param amount    订单金额，单位元，不能为 null，且必须 >= 0
     * @param itemCount 件数，不能小于 0
     * @return 配送费，保留 2 位小数
     * @throws IllegalArgumentException 输入非法时抛出
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        validateAmount(amount);
        validateItemCount(itemCount);

        if (itemCount == 0) {
            return scale2(ZERO);
        }

        if (amount.compareTo(TWO_HUNDRED) > 0) {
            return scale2(ZERO);
        }

        return scale2(DELIVERY_FEE);
    }

    /**
     * 服务费规则：
     * 1. amount == 0 返回 0；
     * 2. 0 < amount <= 100 返回 2；
     * 3. amount > 100 返回 5。
     *
     * @param amount 订单金额，单位元，不能为 null，且必须 >= 0
     * @return 服务费，保留 2 位小数
     * @throws IllegalArgumentException 输入非法时抛出
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        validateAmount(amount);

        if (amount.compareTo(ZERO) == 0) {
            return scale2(ZERO);
        }

        if (amount.compareTo(ONE_HUNDRED) <= 0) {
            return scale2(SERVICE_FEE_LOW);
        }

        return scale2(SERVICE_FEE_HIGH);
    }

    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("amount must not be null");
        }
        if (amount.compareTo(ZERO) < 0) {
            throw new IllegalArgumentException("amount must be >= 0");
        }
    }

    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("itemCount must be >= 0");
        }
    }

    private static BigDecimal scale2(BigDecimal value) {
        return value.setScale(2, RoundingMode.UNNECESSARY);
    }
}
