```java
public class FeeCalculatorTest {
    public static void main(String[] args) {
        testDeliveryFee();
        testServiceFee();
        System.out.println("All tests passed.");
    }

    private static void assertEquals(BigDecimal expected, BigDecimal actual, String message) {
        if (expected.compareTo(actual) != 0) {
            throw new AssertionError(message + " expected: " + expected + " but was: " + actual);
        }
    }

    private static void assertThrows(Class<? extends Exception> expectedType, Runnable runnable, String message) {
        try {
            runnable.run();
            throw new AssertionError(message + " - expected exception " + expectedType.getSimpleName());
        } catch (Exception e) {
            if (!expectedType.isInstance(e)) {
                throw new AssertionError(message + " - expected " + expectedType.getSimpleName() + " but got " + e.getClass().getSimpleName());
            }
        }
    }

    private static void testDeliveryFee() {
        // 件数0
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("0"), 0), "deliveryFee(0,0)");
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("200"), 0), "deliveryFee(200,0)");
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("200.01"), 0), "deliveryFee(200.01,0)");

        // 件数1，金额0
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("0"), 1), "deliveryFee(0,1)");

        // 件数1，金额100
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("100"), 1), "deliveryFee(100,1)");

        // 件数1，金额200（恰好200不免配送）
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("200"), 1), "deliveryFee(200,1)");

        // 件数1，金额200.01（严格大于200免配送）
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("200.01"), 1), "deliveryFee(200.01,1)");

        // 件数1，金额199.99
        assertEquals(new BigDecimal("12.00"), FeeCalculator.deliveryFee(new BigDecimal("199.99"), 1), "deliveryFee(199.99,1)");

        // 件数1，金额201
        assertEquals(new BigDecimal("0.00"), FeeCalculator.deliveryFee(new BigDecimal("201"), 1), "deliveryFee(201,1)");

        // 负数金额
        assertThrows(IllegalArgumentException.class, () -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1), "deliveryFee(-0.01,1)");

        // null金额
        assertThrows(IllegalArgumentException.class, () -> FeeCalculator.deliveryFee(null, 1), "deliveryFee(null,1)");

        // 负数件数
        assertThrows(IllegalArgumentException.class, () -> FeeCalculator.deliveryFee(new BigDecimal("100"), -1), "deliveryFee(100,-1)");
    }

    private static void testServiceFee() {
        // 金额0
        assertEquals(new BigDecimal("0.00"), FeeCalculator.serviceFee(new BigDecimal("0")), "serviceFee(0)");

        // 金额0.01
        assertEquals(new BigDecimal("2.00"), FeeCalculator.serviceFee(new BigDecimal("0.01")), "serviceFee(0.01)");

        // 金额100（不超过100）
        assertEquals(new BigDecimal("2.00"), FeeCalculator.serviceFee(new BigDecimal("100")), "serviceFee(100)");

        // 金额100.01（严格大于100）
        assertEquals(new BigDecimal("5.00"), FeeCalculator.serviceFee(new BigDecimal("100.01")), "serviceFee(100.01)");

        // 金额99.99
        assertEquals(new BigDecimal("2.00"), FeeCalculator.serviceFee(new BigDecimal("99.99")), "serviceFee(99.99)");

        // 金额101
        assertEquals(new BigDecimal("5.00"), FeeCalculator.serviceFee(new BigDecimal("101")), "serviceFee(101)");

        // 负数金额
        assertThrows(IllegalArgumentException.class, () -> FeeCalculator.serviceFee(new BigDecimal("-0.01")), "serviceFee(-0.01)");

        // null金额
        assertThrows(IllegalArgumentException.class, () -> FeeCalculator.serviceFee(null), "serviceFee(null)");
    }
}
